const lockServiceItems = `-- name: LockServiceItems :many
SELECT id, uuid, service_id, organization_id, brand_id, product_id, unit_id, kind, quantity, meters, applied_parts, notes, stock_movement_id, created_at, updated_at FROM service_items
WHERE service_id = $1
ORDER BY id
FOR UPDATE
`

// Completion locks the lines in id order (deadlock-free with concurrent
// completions sharing a unit).
func (q *Queries) LockServiceItems(ctx context.Context, serviceID int64) ([]ServiceItem, error) {
	rows, err := q.db.Query(ctx, lockServiceItems, serviceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ServiceItem{}
	for rows.Next() {
		var i ServiceItem
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.ServiceID,
			&i.OrganizationID,
			&i.BrandID,
			&i.ProductID,
			&i.UnitID,
			&i.Kind,
			&i.Quantity,
			&i.Meters,
			&i.AppliedParts,
			&i.Notes,
			&i.StockMovementID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

